  if (/\bpython3?\b/.test(command)) return ".py"
  if (/\b(node|bun|deno)\b/.test(command)) return ".mjs"
  if (/\b(tsx|ts-node)\b/.test(command)) return ".ts"
  if (/\bgo\s+run\b/.test(command)) return ".go"
