export function summarizeProbe(res) {
  if (!res.ok) return `PROBE ERROR: ${res.error}`
  return `PROBE exit=${res.exitCode}${res.timedOut ? " (timed out)" : ""} (executed in a throwaway copy of the project; nothing was kept)\n${res.output}`
}
